import{_ as a,o as n,c as t,a3 as o}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Research on Yuanyuan Manor Tip Money and Themed Earnings","description":"","frontmatter":{"translationSource":{"title":"关于缘缘庄赏钱与主题收益的研究","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=H3BmVSTclK5aAnaHlaRWQI","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/research-on-yuanyuan-manor-tip-money-and-themed-earnings"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/research-on-yuanyuan-manor-tip-money-and-themed-earnings"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/research-on-yuanyuan-manor-tip-money-and-themed-earnings"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/research-on-yuanyuan-manor-tip-money-and-themed-earnings"}]]},"headers":[],"relativePath":"research-on-yuanyuan-manor-tip-money-and-themed-earnings.md","filePath":"logistics/src/page-H3BmVSTclK5aAnaHlaRWQI.md"}'),r={name:"research-on-yuanyuan-manor-tip-money-and-themed-earnings.md"};function i(s,e,l,d,p,u){return n(),t("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><h1 id="research-on-yuanyuan-manor-tip-money-and-themed-earnings" tabindex="-1">Research on Yuanyuan Manor Tip Money and Themed Earnings <a class="header-anchor" href="#research-on-yuanyuan-manor-tip-money-and-themed-earnings" aria-label="Permalink to &quot;Research on Yuanyuan Manor Tip Money and Themed Earnings&quot;">​</a></h1><blockquote><p>Source page ID: <code>H3BmVSTclK5aAnaHlaRWQI</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=H3BmVSTclK5aAnaHlaRWQI" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Data is currently being collected. Once the research is complete, it will be incorporated into the <a href="/endfield-skydoc/yuanyuan-manor-assistant">Yuanyuan Manor Assistant</a> subpage.</p><p>#jnk:</p><p>At Yuanyuan Manor, a level-four ordinary guest gives 25% tip money; each popular trend adds 10%; delicacies apparently add about 20%.</p><p>The doubling of tips during Full House (满堂彩; provisional English name) may apply to the 25% portion; it apparently amounts to an additional 33%.</p><p>乐在其中: 10-20 11:58:51</p><p>The most accurate method is to run many trials and calculate the average cost and earnings (?).</p><p>乐在其中: 10-20 11:59:30</p><p>In my experience, the final tip money for the Truly Wholesome theme is usually 64%–71% of the base value.</p><p>Roughly, one guest arrives every 12.5 s on average, and takes about 9 s to place an order.</p><p>13x286: 11-03 21:45:00<br> Depending on how quickly food is served, Yuanyuan Manor tips are the original price * 0.2 to 0.24, multiplied by the level-4 inn bonus of 1.25, plus * 0.1 of that dish&#39;s price for each matching attribute. After that total is calculated, apply the Full House doubling * 2.</p><p>13x286: 11-03 21:46:05<br> For example, if a dish at 110 + a drink at 60 were sold, and the dish matched one attribute, the range would be 53.5 to 62, rounded down.</p><blockquote><p>Translation note: 满堂彩 is an activatable popularity-based state in Yuanyuan Manor restaurant management. Full House remains a provisional English name. The source now questions which portion of tip money is doubled; this revision preserves that uncertainty.</p></blockquote></div>',1)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
